package com.badlogic.gdx.scenes.scene2d.utils;

import javax.annotation.Nullable;
import com.badlogic.gdx.graphics.Color;
import com.badlogic.gdx.graphics.g2d.Batch;
import com.badlogic.gdx.graphics.g2d.NinePatch;

/**
 * Drawable for a {@link NinePatch}.
 *
 * <p>The drawable sizes are set when the ninepatch is set, but they are separate values. Eg, {@link
 * Drawable#getLeftWidth()} could be set to more than {@link NinePatch#getLeftWidth()} in order to
 * provide more space on the left than actually exists in the ninepatch.
 *
 * <p>The min size is set to the ninepatch total size by default. It could be set to the left+right
 * and top+bottom, excluding the middle size, to allow the drawable to be sized down as small as
 * possible.
 *
 * @author Nathan Sweet
 */
public class NinePatchDrawable extends BaseDrawable implements TransformDrawable {
  @Nullable private NinePatch patch;

  /**
   * Creates an uninitialized NinePatchDrawable. The ninepatch must be {@link #setPatch(NinePatch)
   * set} before use.
   */
  public NinePatchDrawable() {}

  public NinePatchDrawable(NinePatch patch) {
    setPatch(patch);
  }

  public NinePatchDrawable(NinePatchDrawable drawable) {
    super(drawable);
    this.patch = drawable.patch;
  }

  public void draw(Batch batch, float x, float y, float width, float height) {
    if (patch == null) {
      throw new IllegalStateException("NinePatchDrawable is not initialized with a NinePatch");
    }
    patch.draw(batch, x, y, width, height);
  }

  public void draw(
      Batch batch,
      float x,
      float y,
      float originX,
      float originY,
      float width,
      float height,
      float scaleX,
      float scaleY,
      float rotation) {
    if (patch == null) {
      throw new IllegalStateException("NinePatchDrawable is not initialized with a NinePatch");
    }
    patch.draw(batch, x, y, originX, originY, width, height, scaleX, scaleY, rotation);
  }

  /**
   * Sets this drawable's ninepatch and set the min width, min height, top height, right width,
   * bottom height, and left width to the patch's padding.
   */
  public void setPatch(@Nullable NinePatch patch) {
    this.patch = patch;
    if (patch != null) {
      setMinWidth(patch.getTotalWidth());
      setMinHeight(patch.getTotalHeight());
      setTopHeight(patch.getPadTop());
      setRightWidth(patch.getPadRight());
      setBottomHeight(patch.getPadBottom());
      setLeftWidth(patch.getPadLeft());
    }
  }

  public NinePatch getPatch() {
    if (patch == null) {
      throw new IllegalStateException("NinePatchDrawable is not initialized with a NinePatch");
    }
    return patch;
  }

  /** Creates a new drawable that renders the same as this drawable tinted the specified color. */
  public NinePatchDrawable tint(Color tint) {
    NinePatchDrawable drawable = new NinePatchDrawable(this);
    drawable.patch = new NinePatch(drawable.getPatch(), tint);
    return drawable;
  }
}
